using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
class ArchiveTests {
 static int checks,failed;static void Check(bool ok,string n){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failed++;}
 static string Usage(DateTime now,long input,long cache,long output,long reasoning){return new JavaScriptSerializer().Serialize(new{timestamp=now.ToString("o"),type="event_msg",payload=new{type="token_count",info=new{total_token_usage=new{input_tokens=input,cached_input_tokens=cache,output_tokens=output,reasoning_output_tokens=reasoning,total_tokens=input+output},last_token_usage=new{input_tokens=999999}}}});}
 static string Frame(DateTime start,double total,object[] conns){return new JavaScriptSerializer().Serialize(new{downloadTotal=total,uploadTotal=0,connections=conns});}
 static object Conn(string id,double down,string[] chain,DateTime start){return new{id=id,download=down,upload=0,chains=chain,start=start.ToString("o")};}
 static bool ServeOnce(System.Net.Sockets.TcpListener listener,string body,bool redirect,string expected){using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){client.ReceiveTimeout=3000;var reader=new StreamReader(stream,System.Text.Encoding.ASCII,false,1024,true);string first=reader.ReadLine(),line;bool auth=false;while(!String.IsNullOrEmpty(line=reader.ReadLine()))if(line=="Authorization: Bearer "+expected)auth=true;string reply=redirect?"HTTP/1.1 302 Found\r\nLocation: http://127.0.0.1:1/\r\nContent-Length: 0\r\nConnection: close\r\n\r\n":"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+System.Text.Encoding.UTF8.GetByteCount(body)+"\r\nConnection: close\r\n\r\n"+body;var bytes=System.Text.Encoding.UTF8.GetBytes(reply);stream.Write(bytes,0,bytes.Length);return first=="GET /connections HTTP/1.1"&&auth;}}
 static int Main(string[] args){Directory.CreateDirectory(args[0]);string folder=Path.Combine(args[0],"data-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var now=new DateTime(2026,10,23,1,0,0,DateTimeKind.Utc);try{
 var store=new MonitorArchive(folder);store.Observe(new SystemSample{Utc=now,Cpu=10,NetworkId="a",Download=100,Upload=10});store.Observe(new SystemSample{Utc=now.AddSeconds(1),Cpu=20,NetworkId="a",Download=100,Upload=10});store.Observe(new SystemSample{Utc=now.AddSeconds(3),Cpu=80,NetworkId="a",Download=100,Upload=10});var hours=store.Range(now.Date,now.Date.AddDays(1));Check(hours.Length==1&&hours[0].Metrics["cpu"].Mean==60,"resource history uses time weighted mean");Check(hours[0].Metrics["cpu"].Peak==80&&hours[0].Metrics["cpu"].HighSeconds==2,"peak and real sampled occupancy duration recorded");Check(hours[0].Download==300&&hours[0].Upload==30,"valid network intervals integrated");store.Observe(new SystemSample{Utc=now.AddHours(1),Cpu=99,NetworkId="a",Download=100,Upload=10});Check(store.Range(now.Date,now.Date.AddDays(1)).Length==1,"sleep gaps never manufacture resource history");store.Flush();var restored=new MonitorArchive(folder);Check(restored.Range(now.Date,now.Date.AddDays(1))[0].Download==300,"resource archive survives restart");hours[0].Metrics["cpu"].Sum=0;Check(store.Range(now.Date,now.Date.AddDays(1))[0].Metrics["cpu"].Mean==60,"UI snapshots cannot mutate archive");
 var token=new CodexUsageArchive(folder);Check(token.Consume(Usage(now,100,30,20,5),"session"),"initial cumulative usage counted once");Check(!token.Consume(Usage(now.AddSeconds(1),100,30,20,5),"session"),"rate limit repeated last usage never double counted");token.Consume(Usage(now.AddSeconds(2),150,50,30,7),"session");var day=token.Range(now.ToLocalTime().Date,now.ToLocalTime().Date.AddDays(1)).Single();Check(day.Total==180&&day.Input==150&&day.Cached==50&&day.Output==30,"cached input and reasoning are subsets not additive totals");Check(!token.Consume(Usage(now,10,0,1,0),"session"),"counter rollback does not fabricate usage");Check(!token.Consume("{\"type\":\"response_item\",\"payload\":{\"type\":\"token_count\"}}","session"),"non usage message ignored");
 string home=Path.Combine(folder,"codex"),sessions=Path.Combine(home,"sessions","2026","10","23");Directory.CreateDirectory(sessions);string id=Guid.NewGuid().ToString();var metadata=new JavaScriptSerializer().Serialize(new{type="session_meta",payload=new{id=id}});string log=Path.Combine(sessions,"rollout-test-"+Guid.NewGuid()+".jsonl");File.WriteAllText(log,metadata+"\n"+Usage(now,200,50,40,8)+"\n");token.Scan(home);long first=token.Range(now.ToLocalTime().Date,now.ToLocalTime().Date.AddDays(1)).Sum(d=>d.Total);token.Scan(home);Check(first==420&&token.Range(now.ToLocalTime().Date,now.ToLocalTime().Date.AddDays(1)).Sum(d=>d.Total)==420,"incremental log cursor avoids rescan double count");var reload=new CodexUsageArchive(folder);reload.Scan(home);Check(reload.Range(now.ToLocalTime().Date,now.ToLocalTime().Date.AddDays(1)).Sum(d=>d.Total)==420,"usage and cursor commit atomically across restart");File.AppendAllText(log,Usage(now.AddSeconds(3),300,80,50,10)+"\n");reload.Scan(home);Check(reload.Range(now.ToLocalTime().Date,now.ToLocalTime().Date.AddDays(1)).Sum(d=>d.Total)==530,"appended usage produces exact cumulative delta");
 var split=new ClashTrafficSource(folder);split.Parse(Frame(now,100,new[]{Conn("direct",50,new[]{"DIRECT","group"},now.AddSeconds(-1)),Conn("proxy",50,new[]{"node","group"},now.AddSeconds(-1))}),now);var value=split.Parse(Frame(now,240,new[]{Conn("direct",90,new[]{"DIRECT","group"},now.AddSeconds(-1)),Conn("proxy",100,new[]{"node","group"},now.AddSeconds(-1))}),now.AddSeconds(1));Check(value.Recorded&&value.DirectDown==40&&value.ProxyDown==50&&value.Unknown==50,"direct proxy and unclassified reconcile to kernel total");Check(!split.Parse(Frame(now,2,new object[0]),now.AddSeconds(2)).Recorded,"kernel restart resets baseline without negative traffic");bool refused=false;try{ClashTrafficSource.Address("http://example.com:9090");}catch(ArgumentException){refused=true;}Check(refused,"controller refuses non loopback hosts");refused=false;try{ClashTrafficSource.Address("http://127.0.0.1:9090/path");}catch(ArgumentException){refused=true;}Check(refused,"controller path cannot be repurposed");split.SaveKey("http://127.0.0.1:9090","fixture-secret");Check(!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(folder,"clash-history-key.dat"))).Contains("fixture-secret"),"controller key encrypted outside settings");
 var listener=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);listener.Start();try{string address="http://127.0.0.1:"+((System.Net.IPEndPoint)listener.LocalEndpoint).Port;split.SaveKey(address,"fixture-secret");var server=System.Threading.Tasks.Task.Run(()=>ServeOnce(listener,Frame(now,0,new object[0]),false,"fixture-secret"));split.Fetch(address,DateTime.UtcNow);Check(server.Result&&split.Status.Contains("已连接"),"real loopback GET uses only requested endpoint and encrypted bearer key");server=System.Threading.Tasks.Task.Run(()=>ServeOnce(listener,"",true,"fixture-secret"));split.Fetch(address,DateTime.UtcNow);Check(server.Result&&split.Status.Contains("未就绪"),"controller redirect refused without forwarding credential");}finally{listener.Stop();}
 var appearance=new TaskbarAppearance{GradientGraphs=true,GraphColor="#117799",GradientEnd="#FFCC00"};appearance.EnsureItems();string stop=appearance.Item("cpu").UsageRamp.Stops[0].Color;appearance.Item("cpu").GradientStart="#FF0000";Check(appearance.Item("cpu").UsageRamp.Stops[0].Color==stop,"legacy bar colors freeze independently from text");appearance.BackgroundGradientEnd="#AA4411";appearance.Validate();Check(appearance.ProtectText,"contrast protection is explicit and enabled");
 }catch(Exception e){Console.WriteLine("FAIL "+e);failed++;}File.WriteAllText(Path.Combine(args[0],"archive-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures=failed}));return failed==0?0:1;}
}
